7027 /// Integer compare with boolean values can always be turned into bitwise ops.
7028 static Instruction *canonicalizeICmpBool(ICmpInst &I,
7029                                          InstCombiner::BuilderTy &Builder) {
7030   Value *A = I.getOperand(0), *B = I.getOperand(1);
7031   assert(A->getType()->isIntOrIntVectorTy(1) && "Bools only");
7032 
7033   // A boolean compared to true/false can be simplified to Op0/true/false in
7034   // 14 out of the 20 (10 predicates * 2 constants) possible combinations.
7035   // Cases not handled by InstSimplify are always 'not' of Op0.
7036   if (match(B, m_Zero())) {
7037     switch (I.getPredicate()) {
7038       case CmpInst::ICMP_EQ:  // A ==   0 -> !A
7039       case CmpInst::ICMP_ULE: // A <=u  0 -> !A
7040       case CmpInst::ICMP_SGE: // A >=s  0 -> !A
7041         return BinaryOperator::CreateNot(A);
7042       default:
7043         llvm_unreachable("ICmp i1 X, C not simplified as expected.");
7044     }
7045   } else if (match(B, m_One())) {
7046     switch (I.getPredicate()) {
7047       case CmpInst::ICMP_NE:  // A !=  1 -> !A
7048       case CmpInst::ICMP_ULT: // A <u  1 -> !A
7049       case CmpInst::ICMP_SGT: // A >s -1 -> !A
